import{H as e,V as t,et as n,j as r}from"./chunks/framework.C_EfTa_6.js";var i=JSON.parse(`{"title":"概念索引","description":"","frontmatter":{"title":"概念索引","order":5},"headers":[],"relativePath":"ai/compute/kernel/concepts.md","filePath":"ai/compute/kernel/concepts.md"}`),a={name:`ai/compute/kernel/concepts.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="大模型推理优化的概念索引" tabindex="-1">大模型推理优化的概念索引 <a class="header-anchor" href="#大模型推理优化的概念索引" aria-label="Permalink to “大模型推理优化的概念索引”">​</a></h1><p>大模型推理优化的概念看似零散（量化、内核、显存、调度），但实际上可以被组织成一张清晰的五层结构。每一层有自己的核心区分维度，上下游之间是单向依赖——下层演进决定上层可能，理解这张图就能避免绝大多数&quot;我应该选什么&quot;的迷茫。本文是 kernel/ 目录下所有文章的概念地图，每篇文章会聚焦在某一层或跨层关系上。</p><h2 id="五层结构概览" tabindex="-1">五层结构概览 <a class="header-anchor" href="#五层结构概览" aria-label="Permalink to “五层结构概览”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 推理引擎层  vLLM / TensorRT-LLM / SGLang / llama.cpp   </span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 内核层    Marlin / Machete / CUTLASS NVFP4 / DeepGEMM  </span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 算法层    AWQ / GPTQ / EXL2 / EXL3 / QuIP# / NVFP4 算法 </span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 精度/格式层  W4A16 / W8A8-FP8 / NVFP4 / K-quant·I-quant·GGUF  </span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 硬件层    Volta / Turing / Ampere / Ada / Hopper / Blackwell </span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>层</th><th>核心区分维度</th><th>回答什么问题</th></tr></thead><tbody><tr><td>硬件层</td><td>架构代际（SM 版本）</td><td>&quot;这块卡能跑什么&quot;</td></tr><tr><td>精度/格式层</td><td>位宽 × 数字格式</td><td>&quot;用什么格式存权重和激活&quot;</td></tr><tr><td>算法层</td><td>量化方法思路</td><td>&quot;怎么把 FP16 模型压成那个格式&quot;</td></tr><tr><td>内核层</td><td>硬件能力 × 输入格式</td><td>&quot;用硬件的新指令怎么算出矩阵乘&quot;</td></tr><tr><td>推理引擎层</td><td>服务特性（批处理/缓存/调度）</td><td>&quot;多个请求怎么串成生产级服务&quot;</td></tr></tbody></table><p>上下游对应关系：上层概念往往直接锚定下层概念——量化算法产出某种权重格式，权重格式必须由特定内核消费，内核必须跑在支持对应硬件能力的 GPU 上。</p><h2 id="硬件层-gpu-架构代际" tabindex="-1">硬件层：GPU 架构代际 <a class="header-anchor" href="#硬件层-gpu-架构代际" aria-label="Permalink to “硬件层：GPU 架构代际”">​</a></h2><p>所有上层决策的物理根基。每代架构都有标志性的新能力，这些能力是上层优化的物质基础。</p><table tabindex="0"><thead><tr><th>代际</th><th>compute capability</th><th>关键新能力</th><th>代表卡</th></tr></thead><tbody><tr><td>Volta</td><td>7.0</td><td>第一代 Tensor Core</td><td>V100</td></tr><tr><td>Turing</td><td>7.5</td><td>INT4 Tensor Core</td><td>RTX 20 系、T4</td></tr><tr><td>Ampere</td><td>8.0 / 8.6</td><td>BF16、TF32、cp.async、Sparse Tensor Core</td><td>RTX 30 系、A100、A10</td></tr><tr><td>Ada Lovelace</td><td>8.9</td><td>FP8 Tensor Core</td><td>RTX 40 系、L40S</td></tr><tr><td>Hopper</td><td>9.0</td><td>wgmma、TMA、FA3、Transformer Engine</td><td>H100、H200</td></tr><tr><td>Blackwell</td><td>10.0+</td><td>FP4 Tensor Core、tcgen05、TMEM</td><td>B100/B200、RTX 50 系</td></tr><tr><td>AMD RDNA3</td><td>gfx1100</td><td>BF16、INT8（无原生 INT4）</td><td>RX 7900 XTX、W7900</td></tr><tr><td>AMD RDNA4</td><td>gfx1200</td><td>与 RDNA3 同源，W4A16 通过 vLLM kernel</td><td>RX 9070 系</td></tr><tr><td>AMD CDNA3</td><td>gfx940</td><td>FP8 / BF16 原生</td><td>MI300X</td></tr><tr><td>AMD CDNA4</td><td>gfx950</td><td>MXFP4 / MXFP6 原生（无 NVFP4）</td><td>MI355X、MI350X</td></tr></tbody></table><p>被上层直接消费的硬件能力：</p><ul><li><code>cp.async</code> — Ampere 起的异步内存拷贝指令，Marlin 的流水线依赖它</li><li><code>mma.sync</code> — 标准 Tensor Core 矩阵乘指令，所有代际都有</li><li><code>wgmma</code> — Hopper 起的 warp group 矩阵乘，Machete 利用它</li><li><code>TMA</code> — Hopper 起的 Tensor Memory Accelerator，Hopper+ 内核的标配</li><li><code>tcgen05.mma</code> — Blackwell 起的 block-scaled 矩阵乘，NVFP4 GEMM 用它</li><li><code>TMEM</code> — Blackwell 的 Tensor Memory，存累加器</li></ul><p>关键约束：没有 cp.async 就跑不了 Marlin，没有 wgmma+TMA 就用不到 Machete 的全部优化，没有 FP4 Tensor Core 就只能模拟 NVFP4。上层概念在某一层断档，下层就吃不到对应优化。</p><h2 id="精度-格式层-数据怎么存" tabindex="-1">精度/格式层：数据怎么存 <a class="header-anchor" href="#精度-格式层-数据怎么存" aria-label="Permalink to “精度/格式层：数据怎么存”">​</a></h2><p>由位宽维度和数字格式维度交叉得到。这层定义的是&quot;权重和激活用什么 bit 表示&quot;。</p><p>位宽维度命名规则：</p><ul><li><code>W</code> = Weight，<code>A</code> = Activation</li><li>后跟数字 = bit 数</li><li>例：<code>W4A16</code> = 权重 4-bit + 激活 16-bit</li></ul><p>数字格式维度：</p><ul><li><code>INT4</code> / <code>INT8</code>：整数</li><li><code>FP8</code> / <code>FP16</code> / <code>BF16</code>：浮点</li><li><code>FP8</code> 又有 <code>E4M3</code> / <code>E5M2</code> 两种细分</li></ul><p>常见组合：</p><table tabindex="0"><thead><tr><th>名称</th><th>权重</th><th>激活</th><th>典型硬件</th><th>备注</th></tr></thead><tbody><tr><td>W4A16</td><td>INT4</td><td>BF16</td><td>Ampere+</td><td>weight-only，主流方案</td></tr><tr><td>W8A8 (INT8)</td><td>INT8</td><td>INT8</td><td>通用</td><td>经典 CV 量化</td></tr><tr><td>W8A8-FP8</td><td>FP8</td><td>FP8</td><td>Ada/Hopper/Blackwell 原生</td><td>Hopper 起最成熟</td></tr><tr><td>W4A8-FP8</td><td>INT4</td><td>FP8</td><td>Hopper</td><td>CUTLASS 路径</td></tr><tr><td>NVFP4</td><td>FP4 + 微块缩放</td><td>FP4</td><td>Blackwell</td><td>终极压缩</td></tr></tbody></table><p>几个容易混淆的点：</p><ul><li><code>W4A16</code> 中的 16 通常是 BF16，不是 FP16。BF16 指数位和 FP32 同宽（8 位），跑 LLM 的 Softmax 不溢出；FP16 指数位只有 5 位，跑大模型长序列会 NaN。</li><li><code>FP8</code> 不指定位宽，只指定数字格式——既可以用于权重（<code>W8A8-FP8</code>），也可以独立存在。</li><li><code>NVFP4</code> 是浮点 4-bit，不是 INT4。微块缩放 + E4M3 scale 让 4-bit 浮点的动态范围接近 FP8，精度比 INT4 高一截。</li></ul><h2 id="算法层-怎么压成低-bit" tabindex="-1">算法层：怎么压成低 bit <a class="header-anchor" href="#算法层-怎么压成低-bit" aria-label="Permalink to “算法层：怎么压成低 bit”">​</a></h2><p>给定一个高精度模型，用什么方法算出低精度版本。这一层产出的是&quot;格式 + 量化参数&quot;的组合。</p><table tabindex="0"><thead><tr><th>算法</th><th>思路</th><th>典型输出</th></tr></thead><tbody><tr><td>GPTQ</td><td>Hessian 矩阵误差最小化（重建法）</td><td>W4A16 权重 + per-channel scale</td></tr><tr><td>AWQ</td><td>保护显著权重（per-channel scaling）</td><td>W4A16 权重 + 放大关键通道</td></tr><tr><td>RTN</td><td>朴素舍入</td><td>任意位宽，质量最差</td></tr><tr><td>EXL2</td><td>GPTQ 思想 + 混合比特</td><td>私有格式，2~8 bpw 混合</td></tr><tr><td>EXL3</td><td>QTIP / Trellis 向量量化</td><td>私有格式，1~8 bpw 混合</td></tr><tr><td>QuIP# / AQLM</td><td>高阶向量量化（学术派）</td><td>W4A16，质量极佳但慢</td></tr><tr><td>NVFP4 量化</td><td>微块缩放 + E4M3 scale</td><td>NVFP4 权重</td></tr></tbody></table><p>算法层的关键区分：</p><ul><li>GPTQ vs AWQ：GPTQ 是&quot;误差补偿&quot;思路（量化一列后用 Hessian 调整剩余权重），对校准数据敏感；AWQ 是&quot;特征保护&quot;思路（识别大激活值通道并放大），量化更快、泛化更好</li><li>EXL2 vs GPTQ/AWQ：EXL2 是私有格式（ExLlamaV2 引擎专用），不能被 Marlin 等通用内核消费；GPTQ/AWQ 是开放格式，工具链最成熟</li><li>NVFP4 量化是 NVIDIA 官方配套的 Blackwell 算法，与 NVFP4 格式强绑定</li></ul><h2 id="内核层-怎么算" tabindex="-1">内核层：怎么算 <a class="header-anchor" href="#内核层-怎么算" aria-label="Permalink to “内核层：怎么算”">​</a></h2><p>给定硬件能力 + 权重格式，怎么用 GPU 的指令把矩阵乘算出来。这一层是上层所有优化的&quot;执行落地&quot;。</p><table tabindex="0"><thead><tr><th>内核</th><th>出品</th><th>输入</th><th>主要目标硬件</th><th>关键依赖</th></tr></thead><tbody><tr><td>Marlin</td><td>IST-DASLab</td><td>W4A16 (AWQ/GPTQ)</td><td>Ampere（消费级 W4A16 王者）</td><td>cp.async</td></tr><tr><td>Sparse-Marlin</td><td>IST-DASLab</td><td>W4A16 + 2:4 稀疏</td><td>Ampere</td><td>稀疏 TC</td></tr><tr><td>Machete</td><td>vLLM</td><td>W4A16</td><td>Hopper（Marlin 继任者）</td><td>wgmma + TMA</td></tr><tr><td>CUTLASS W4A8</td><td>NVIDIA</td><td>INT4 + FP8</td><td>Hopper</td><td>wgmma + TMA</td></tr><tr><td>CUTLASS NVFP4 GEMM</td><td>NVIDIA</td><td>NVFP4</td><td>Blackwell</td><td>tcgen05.mma + TMEM</td></tr><tr><td>DeepGEMM</td><td>DeepSeek-AI</td><td>FP8 / NVFP4</td><td>Blackwell SM100</td><td>tcgen05.mma</td></tr><tr><td>TensorRT-Edge-LLM CuTe DSL</td><td>NVIDIA</td><td>NVFP4 grouped</td><td>Blackwell SM120</td><td>mma.sync.aligned.block_scale</td></tr><tr><td>ExLlamaV2 q_gemm</td><td>turboderp</td><td>EXL2</td><td>Ampere/Ada（小 batch 极快）</td><td>私有手写 CUDA</td></tr><tr><td>cuDNN / cuBLASLt</td><td>NVIDIA</td><td>FP8/BF16</td><td>全硬件</td><td>通用库</td></tr><tr><td>vLLM Native W4A16</td><td>vLLM 社区</td><td>W4A16 (AWQ/GPTQ)</td><td>AMD RDNA3 (gfx1100)</td><td>ROCm HIP / BF16 原生支持</td></tr><tr><td>HybridW4A16</td><td>vLLM</td><td>W4A16</td><td>AMD 跨平台</td><td>Triton 大 batch + HIP skinny 小 batch</td></tr><tr><td>AMD MXFP4 GEMM</td><td>AMD</td><td>MXFP4</td><td>CDNA4 (MI355X)</td><td>原生 OCP MXFP4 指令</td></tr><tr><td>NVFP4 → MXFP4 重量化</td><td>AMD</td><td>NVFP4 checkpoint</td><td>CDNA4 (MI355X)</td><td>在线反量化到 MXFP4</td></tr></tbody></table><p>内核层的几个关键映射（这是选型矩阵的底层依据）：</p><ul><li>AWQ/GPTQ → Marlin 是 Ampere 时代 W4A16 的事实标准（<a href="./marlin">Marlin</a>）</li><li>W4A16 → Machete 是 Hopper 上替代 Marlin 的选择</li><li>NVFP4 → CUTLASS + DeepGEMM + TensorRT-Edge-LLM 是 Blackwell 上的多源方案，目前没有一个统一的内核名字（<a href="./quant_matrix">量化选型</a>）</li><li>EXL2 → ExLlamaV2 q_gemm 是单用户极致速度方案，与 Marlin 不兼容</li></ul><h2 id="推理引擎层-怎么服务" tabindex="-1">推理引擎层：怎么服务 <a class="header-anchor" href="#推理引擎层-怎么服务" aria-label="Permalink to “推理引擎层：怎么服务”">​</a></h2><p>把单次推理调用串成生产级服务。这一层关心的是&quot;多个请求怎么排队、怎么共享显存、怎么调度&quot;。</p><table tabindex="0"><thead><tr><th>引擎</th><th>标志特性</th><th>内核消费</th></tr></thead><tbody><tr><td>vLLM</td><td>Continuous Batching + PagedAttention</td><td>Marlin / Machete / CUTLASS / DeepGEMM 全选</td></tr><tr><td>TensorRT-LLM</td><td>NVIDIA 官方优化</td><td>CUTLASS + TensorRT 引擎</td></tr><tr><td>SGLang</td><td>RadixAttention（前缀缓存激进）</td><td>FlashAttention + 各类量化内核</td></tr><tr><td>llama.cpp</td><td>GGUF + CPU+GPU 混合</td><td>自家 q_gemm</td></tr><tr><td>ExLlamaV2 / TabbyAPI</td><td>单卡单用户极致速度</td><td>自家 q_gemm（EXL2）</td></tr><tr><td>Transformers</td><td>HF 官方，慢但通用</td><td>通用 GEMM</td></tr></tbody></table><p>这一层的关键概念：</p><ul><li><code>Prefill</code> vs <code>Decode</code> — 两种推理阶段，对应不同瓶颈（Compute-Bound vs Memory-Bound）</li><li><code>Continuous Batching</code> — vLLM 标志特性，请求随时进出</li><li><code>PagedAttention</code> — vLLM 的显存分页管理</li><li><code>RadixAttention</code> — SGLang 的前缀缓存</li><li><code>Chunked Prefill</code> — 长 prompt 切块与 Decode 并发</li><li><code>Prefix Caching</code> — 通用概念，SGLang 做到极致</li></ul><p>引擎与内核的关系：引擎是&quot;调度框架&quot;，内核是&quot;计算单元&quot;。vLLM 选择哪个内核，取决于模型权重格式 + GPU 架构；用户不需要直接选内核，vLLM 会自动路由。</p><h2 id="跨层对应关系速查" tabindex="-1">跨层对应关系速查 <a class="header-anchor" href="#跨层对应关系速查" aria-label="Permalink to “跨层对应关系速查”">​</a></h2><p>关键约束：上层概念往往直接锚定下层概念。错位使用会失去硬件加速的根基。</p><table tabindex="0"><thead><tr><th>上层</th><th>下层</th><th>错位后果</th></tr></thead><tbody><tr><td>Marlin</td><td>Ampere 起（cp.async）</td><td>Turing 缺 cp.async，无法流水线</td></tr><tr><td>Machete</td><td>Hopper（wgmma + TMA）</td><td>Ampere 上没新指令可用</td></tr><tr><td>NVFP4</td><td>Blackwell（FP4 TC）</td><td>Ada 上没原生 FP4，软件模拟</td></tr><tr><td>W4A16 + Marlin</td><td>显存 ~1/4 of FP16</td><td>因为 weight-only，不动激活</td></tr><tr><td>FP8</td><td>Ada/Hopper/Blackwell 原生</td><td>Ampere 上自动反量化到 FP16</td></tr><tr><td>EXL2 权重</td><td>ExLlamaV2 引擎专用</td><td>不能直接用 vLLM + Marlin</td></tr></tbody></table><h2 id="五层的一句话总结" tabindex="-1">五层的一句话总结 <a class="header-anchor" href="#五层的一句话总结" aria-label="Permalink to “五层的一句话总结”">​</a></h2><p>硬件层决定&quot;能跑什么&quot;，精度层决定&quot;用什么格式存&quot;，算法层决定&quot;怎么压成那个格式&quot;，内核层决定&quot;用硬件能力怎么算那个格式&quot;，推理引擎层决定&quot;把多个调用串成什么服务模式&quot;——五层之间是单向依赖，下层的演进决定上层的可能。</p><h2 id="阅读路径建议" tabindex="-1">阅读路径建议 <a class="header-anchor" href="#阅读路径建议" aria-label="Permalink to “阅读路径建议”">​</a></h2><ul><li>刚接触推理优化：先读 <a href="./marlin">Marlin</a> 建立单内核的完整心智模型，再读 <a href="./quant_matrix">量化选型</a> 看跨架构选型</li><li>关心部署：先读 <a href="./quantization">量化</a> 理解算法层（GPTQ/AWQ），再读 <a href="./format">模型格式</a> 理解权重存储</li><li>关心底层：先读 <a href="./optimization">算子优化</a> 看通用 kernel 设计原则，再回来看 <a href="./marlin">Marlin</a> 和 <a href="./flashattention">FlashAttention</a> 的具体实现</li><li>关心推理服务：先读本文的&quot;推理引擎层&quot;，再看 vLLM / SGLang 等专门文章</li></ul>`,45)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};